def solve(M):
    s1 = 0
    for n in range(1, M):
        term1 = (M**n)
        for k in range(1, n+1):
            term1 /= (M + k)
        s1 += term1

    s2 = 0
    for n in range(1, M):
        term2 = 1
        for k in range(1, n+1):
            term2 *= (1 - k/M)
        s2 += term2

    return s1 - s2

